sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var requestUser = request.pathParams ? request.pathParams.user_name : null;
    var requestNIQuery = request.queryParams ? request.queryParams.ni_query : null;

    if (!requestUser) {
        response.setBody({ error: "Missing required parameter: user_name" });
        return;
    }

    var requestUserName = new GlideRecord('sys_user');
    requestUserName.get('user_name', requestUser);

    if (!requestUserName.isValidRecord()) {
        response.setBody({ error: "User not found" });
        return;
    }

    var userNICount = new GlideAggregate('x_58872_needit_needit');
    userNICount.addAggregate('COUNT');
    userNICount.addQuery('u_requested_for', requestUserName.getValue('sys_id'));
    if (requestNIQuery) {
        userNICount.addEncodedQuery(requestNIQuery);
    }
    userNICount.groupBy('u_request_type');
    userNICount.query();

    var niUserRecs = [];
    var needitRecsCount = 0;

    while (userNICount.next()) {
        var needitRecs = userNICount.getAggregate('COUNT');
        var reqType = userNICount.getDisplayValue('u_request_type');
        niUserRecs.push({ "requestType": reqType, "count": Number(needitRecs) });
        needitRecsCount += Number(needitRecs);
    }

    var body = {
        totalUserNIRecs: needitRecsCount,
        catCounts: niUserRecs,
        user: {
            "User name": requestUserName.getValue('user_name'),
            "User ID": requestUserName.getValue('sys_id')
        }
    };

    response.setBody(body);

})(request, response);
